  ["Oh, too bad..."] = "Ah, que pena...",
  ["Missed!"] = "Errou!",
  ["So close..."] = "Foi por pouco...",
  ["Shake it off"] = "Deixa pra lá",
  ["Next one!"] = "Vamos à próxima!",
  ["Great streak!"] = "Ótima sequência!",
  ["Keep it up!"] = "Continue assim!",
  ["Blazing!"] = "Em chamas!",
  ["Streak Champion!"] = "Campeão de sequência!",
  ["Godlike!"] = "Divino!",
  ["Immortal!"] = "Imortal!",
  ["Game timing offset"] = "Ajuste de tempo do modo jogo",
  ["Game mode: moves the moment a note reaches the line (and flashes). If your presses feel late, raise it: the note arrives that much sooner. Like a rhythm game's calibration."] = "Modo jogo: move o momento em que uma nota chega à linha (e pisca). Se seus toques parecem atrasados, aumente: a nota chega mais cedo. Como a calibração de um jogo de ritmo.",
  ["Game score %d, best streak %d, %d%% perfect"] = "Pontos do jogo %d, melhor sequência %d, %d%% perfeitos",
  ["(new high score)"] = "(novo recorde)",
  ["Clears the best streak and best set score of the spec you are in. Other specs keep theirs."] = "Apaga a melhor sequência e a melhor pontuação de set da especialização atual. As outras mantêm as delas.",
  ["Core"] = "Núcleo",
  ["Core settings"] = "Configurações principais",
  ["Describe what went wrong, copy the report, and open the issue page (also /dmga report)."] = "Descreva o que deu errado, copie o relatório e abra a página de problemas (também /dmga report).",
  ["Forget this spec's game records"] = "Esquecer os recordes de jogo desta especialização",
  ["Four questions: where the HUD goes, how big, when it shows, and classic or Game mode."] = "Quatro perguntas: onde fica o HUD, qual tamanho, quando aparece, e clássico ou modo jogo.",
  ["Game mode & grades"] = "Modo jogo e notas",
  ["Game records for this spec forgotten."] = "Recordes de jogo desta especialização esquecidos.",
  ["How DMGAssist thinks and looks: Combat, Display, Sounds, Integrations, Spells & trinkets and Advanced, on the pages below."] = "Como o DMGAssist pensa e aparece: Combate, Exibição, Sons, Integrações, Feitiços e berloques e Avançado, nas páginas abaixo.",
  ["Play the HUD like a rhythm game, or keep the classic icons. Switch any time with the drum button on the HUD, /dmga game, or a key binding."] = "Jogue o HUD como um jogo de ritmo ou mantenha os ícones clássicos. Troque quando quiser com o botão do tambor no HUD, /dmga game ou uma tecla.",
  ["Records"] = "Recordes",
  ["Report"] = "Relatar",
  ["Status & Help"] = "Status e ajuda",
  ["Turn DMGAssist on or off, move it, and pick its language. Everything else is in three groups below: Status & Help, Core (Combat, Display, Sounds, Integrations, Advanced) and Game mode & grades."] = "Ligue ou desligue o DMGAssist, mova-o e escolha o idioma. Todo o resto está em três grupos abaixo: Status e ajuda, Núcleo (Combate, Exibição, Sons, Integrações, Avançado) e Modo jogo e notas.",
  ["What DMGAssist sees right now (Status), how to use it (Help), and spells it may recommend that have no key yet (Missing keybinds): the pages below."] = "O que o DMGAssist vê agora (Status), como usá-lo (Ajuda) e feitiços recomendáveis sem tecla (Teclas faltando): as páginas abaixo.",
  ["KICK!"] = "INTERROMPA!",
  ["DEFEND!"] = "DEFENDA-SE!",
  ["POWER UP!"] = "PODER!",
  ["Interrupted!"] = "Interrompido!",
  ["Safe!"] = "A salvo!",
  ["Powered up!"] = "Fortalecido!",
  ["Bonus +%d"] = "Bônus +%d",
  ["Play the HUD like a rhythm game: notes slide right to left into a line and reach it when the spell can be pressed. Interrupts, defensives and trinkets pop into the bonus row above it. Hits build a streak; 5, 10, 25, 50 in a row earn a star. Switch any time with the drum button on the HUD or /dmga game."] = "Jogue o HUD como um jogo de ritmo: as notas deslizam da direita para a esquerda até uma linha e chegam nela quando o feitiço pode ser usado. Interrupções, defensivas e berloques aparecem na fileira de bônus acima. Acertos formam uma sequência; 5, 10, 25, 50 seguidos valem uma estrela. Troque quando quiser com o botão do tambor no HUD ou /dmga game.",
  ["POWER MODE!"] = "MODO PODER!",
  ["AOE"] = "AOE",
  ["PERFECT x%d"] = "PERFEITO x%d",
  ["CLASSIC"] = "CLÁSSICO",
  ["GAME"] = "JOGO",
  ["Game mode on: hit each note as it reaches the line. Click the CLASSIC / GAME switch (or /dmga game) to switch back."] = "Modo jogo ligado: acerte cada nota quando ela chegar à linha. Clique no interruptor CLÁSSICO / JOGO (ou /dmga game) para voltar.",
  ["Play the HUD like a rhythm game, or keep the classic icons. Switch any time with the CLASSIC / GAME switch above the HUD, /dmga game, or a key binding."] = "Jogue o HUD como um jogo de ritmo ou mantenha os ícones clássicos. Troque quando quiser com o interruptor CLÁSSICO / JOGO acima do HUD, /dmga game ou uma tecla.",
  ["Play the HUD like a rhythm game: notes slide right to left into a line and reach it when the spell can be pressed. Interrupts, defensives and trinkets pop into the bonus row above it. Hits build a streak; 5, 10, 25, 50 in a row earn a star. Switch any time with the CLASSIC / GAME switch above the HUD or /dmga game."] = "Jogue o HUD como um jogo de ritmo: as notas deslizam da direita para a esquerda até uma linha e chegam nela quando o feitiço pode ser usado. Interrupções, defensivas e berloques aparecem na fileira de bônus acima. Acertos formam uma sequência; 5, 10, 25, 50 seguidos valem uma estrela. Troque quando quiser com o interruptor CLÁSSICO / JOGO acima do HUD ou /dmga game.",
  ["Which style? (Switch any time with the CLASSIC / GAME switch above the HUD, or /dmga game.)"] = "Qual estilo? (Troque quando quiser com o interruptor CLÁSSICO / JOGO acima do HUD, ou /dmga game.)",
}
